export async function listTools() {
  return [
    {
      name: 'catalog_search',
      description: 'Search the catalog by item name (case-insensitive) with pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Substring to search for in item names (case-insensitive).' },
          offset: { type: 'integer', minimum: 0, default: 0, description: 'Number of matching rows to skip.' },
          limit: { type: 'integer', minimum: 1, maximum: 5, default: 2, description: 'Maximum number of rows to return (1-5).' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

function isInteger(v) {
  return typeof v === 'number' && Number.isInteger(v);
}

export async function callTool(name, args) {
  if (name !== 'catalog_search') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { query, offset = 0, limit = 2 } = args || {};

  // Validate query: required, must be a string
  if (typeof query !== 'string') {
    throw new Error('query is required and must be a string');
  }

  // Validate offset: optional, must be a non-negative integer
  if (!isInteger(offset) || offset < 0) {
    throw new Error('offset must be a non-negative integer');
  }

  // Validate limit: optional, must be an integer in range 1-5
  if (!isInteger(limit) || limit < 1 || limit > 5) {
    throw new Error('limit must be an integer between 1 and 5');
  }

  // Reject extra/unknown arguments
  const known = new Set(['query', 'offset', 'limit']);
  for (const key of Object.keys(args || {})) {
    if (!known.has(key)) {
      throw new Error(`Unexpected argument: ${key}`);
    }
  }

  const needle = query.toLowerCase();
  const matches = items.filter((it) => it.name.toLowerCase().includes(needle));
  const slice = matches.slice(offset, offset + limit);
  const hasNext = offset + limit < matches.length;

  const payload = {
    results: slice,
    count: slice.length,
    total: matches.length,
    ...(hasNext ? { next_offset: offset + limit } : {})
  };

  return {
    content: [{ type: 'text', text: JSON.stringify(payload) }]
  };
}

